// Polices
.poppins-thin  {

  font-family: "Poppins", sans-serif;

  font-weight: 100;

  font-style: normal;

}

.poppins-extralight  {

  font-family: "Poppins", sans-serif;

  font-weight: 200;

  font-style: normal;

}

.poppins-light  {

  font-family: "Poppins", sans-serif;

  font-weight: 300;

  font-style: normal;

}

.poppins-regular  {

  font-family: "Poppins", sans-serif;

  font-weight: 400;

  font-style: normal;

}

.kaisei-decol-regular  {

  font-family: "Kaisei Decol", serif;

  font-weight: 400;

  font-style: normal;

}

// Reset & Base
*  {

  margin: 0;

  padding: 0;

  box-sizing: border-box;

}

body  {

  font-family: "Poppins", sans-serif;

  line-height: 1.6;

  color: $black;

}

a  {

  text-decoration: none;

  color: inherit;

}

img  {

  max-width: 100%;

  height: auto;

}

// Header
header  {

  background: $white;

  padding: 1rem 2rem;

  display: flex;

  justify-content: space-between;

  align-items: center;

  position: sticky;

  top: 0;

  z-index: 100;

  box-shadow: 0 2px 5px rgba(0,0,0,0.1);

  .logo  {

    font-family: "Kaisei Decol", serif;

    font-size: 1.8rem;

    font-weight: 400;

  }

  nav ul  {

    display: flex;

    list-style: none;

    gap: 2rem;

    li a  {

      font-weight: 500;

      transition: color 0.3s;

      &:hover  {

        color: $primary-color;

      }

    }

  }

}

// Hero Section
.hero  {

  background: url('assets/images/hero.jpg') no-repeat center center;

  background-size: cover;

  height: 60vh;

  display: flex;

  align-items: center;

  justify-content: center;

  text-align: center;

  color: $white;

  position: relative;

  &::before  {

    content: '';

    position: absolute;

    top: 0;

    left: 0;

    width: 100%;

    height: 100%;

    background: rgba(0,0,0,0.4);

  }

  h1  {

    font-family: "Kaisei Decol", serif;

    font-size: 3rem;

    z-index: 1;

    text-shadow: 2px 2px 4px rgba(0,0,0,0.5);

  }

}

// Quote Section
.quote  {

  padding: 3rem 2rem;

  text-align: center;

  background: $white;

  blockquote  {

    font-family: "Kaisei Decol", serif;

    font-size: 1.5rem;

    font-style: italic;

    margin-bottom: 1rem;

  }

  cite  {

    display: block;

    font-weight: 500;

  }

}

// Description Box
.description  {

  max-width: 800px;

  margin: 2rem auto;

  padding: 2rem;

  border: 1px solid $black;

  text-align: center;

}

// Signature Pastries
.signature  {

  background: $primary-color;

  padding: 3rem 2rem;

  color: $white;

  text-align: center;

  h2  {

    font-family: "Kaisei Decol", serif;

    margin-bottom: 2rem;

  }

  .pastries  {

    display: flex;

    justify-content: center;

    gap: 2rem;

    flex-wrap: wrap;

    .pastry  {

      background: rgba($white, 0.1);

      padding: 1.5rem;

      border-radius: 10px;

      max-width: 300px;

      img  {

        border-radius: 10px;

        margin-bottom: 1rem;

      }

      h3  {

        margin: 1rem 0;

        font-family: "Kaisei Decol", serif;

      }

      p  {

        font-size: 0.9rem;

      }

    }

  }

  .btn  {

    display: inline-block;

    margin-top: 2rem;

    padding: 0.75rem 1.5rem;

    background: $white;

    color: $primary-color;

    border: 1px solid $white;

    border-radius: 5px;

    transition: all 0.3s;

    &:hover  {

      background: transparent;

      color: $white;

    }

  }

}

// History Section
.history  {

  padding: 3rem 2rem;

  display: flex;

  align-items: center;

  gap: 2rem;

  flex-wrap: wrap;

  .image  {

    flex: 1;

    min-width: 300px;

    img  {

      border-radius: 50%;

      box-shadow: 0 0 20px rgba(0,0,0,0.1);

      display: block;

      margin: 0 auto;

      max-width: 450px;

    }

  }

  .text  {

    flex: 1;

    min-width: 300px;

    h2  {

      font-family: "Kaisei Decol", serif;

      margin-bottom: 1rem;

    }

    p  {

      margin-bottom: 1rem;

    }

    .btn  {

      padding: 0.75rem 1.5rem;

      background: $primary-color;

      color: $white;

      border: none;

      border-radius: 5px;

      cursor: pointer;

    }

  }

}

// Event Form
.event  {

  padding: 3rem 2rem;

  background: $white;

  display: flex;

  gap: 2rem;

  flex-wrap: wrap;

  .text  {

    flex: 1;

    min-width: 300px;

    h2  {

      font-family: "Kaisei Decol", serif;

      margin-bottom: 1rem;

    }

    p  {

      margin-bottom: 1rem;

    }

  }

  form  {

    flex: 1;

    min-width: 300px;

    .form-group  {

      margin-bottom: 1rem;

      label  {

        display: block;

        margin-bottom: 0.5rem;

      }

      input, textarea  {

        width: 100%;

        padding: 0.5rem;

        border: 1px solid #ccc;

        border-radius: 5px;

      }

    }

    .checkbox  {

      display: flex;

      align-items: center;

      gap: 0.5rem;

      margin: 1rem 0;

    }

    .btn  {

      width: 100%;

      padding: 0.75rem;

      background: $primary-color;

      color: $white;

      border: none;

      border-radius: 5px;

      cursor: pointer;

    }

  }

}

// Map Section
.map  {

  background: $primary-color;

  padding: 2rem;

  text-align: center;

  color: $white;

  h2  {

    font-family: "Kaisei Decol", serif;

    margin-bottom: 1rem;

  }

  p  {

    margin-bottom: 1rem;

  }

  iframe  {

    width: 100%;

    height: 300px;

    border: none;

    border-radius: 10px;

  }

}

// Footer
footer  {

  background: $black;

  color: $white;

  padding: 2rem;

  display: flex;

  flex-wrap: wrap;

  gap: 2rem;

  justify-content: space-between;

  .logo  {

    font-family: "Kaisei Decol", serif;

    font-size: 1.5rem;

  }

  .links  {

    display: flex;

    flex-direction: column;

    gap: 0.5rem;

    a  {

      color: $white;

      &:hover  {

        color: $primary-color;

      }

    }

  }

  .contact  {

    display: flex;

    flex-direction: column;

    gap: 0.5rem;

    .phone  {

      font-weight: bold;

    }

    .address  {

      white-space: pre-line;

    }

  }

  .hours  {

    display: flex;

    flex-direction: column;

    gap: 0.5rem;

    strong  {

      font-weight: bold;

    }

  }

  .social  {

    display: flex;

    flex-direction: column;

    gap: 0.5rem;

    h4  {

      margin-bottom: 0.5rem;

    }

    .icons  {

      display: flex;

      gap: 1rem;

      a  {

        font-size: 1.5rem;

        color: $white;

        &:hover  {

          color: $primary-color;

        }

      }

    }

  }

  .legal  {

    width: 100%;

    text-align: center;

    margin-top: 1rem;

    border-top: 1px solid rgba($white, 0.2);

    padding-top: 1rem;

    font-size: 0.8rem;

    a  {

      color: $white;

      margin: 0 1rem;

      &:hover  {

        color: $primary-color;

      }

    }

  }

}

// Responsive
@media (max-width: 768px)  {

  header  {

    flex-direction: column;

    gap: 1rem;

  }

  .hero h1  {

    font-size: 2rem;

  }

  .signature .pastries  {

    flex-direction: column;

    align-items: center;

  }

  .history  {

    flex-direction: column;

  }

  .event  {

    flex-direction: column;

  }

  footer  {

    flex-direction: column;

    align-items: center;

    text-align: center;

    .social  {

      .icons  {

        justify-content: center;

      }

    }

  }

}

